#### Phase 2: Instrument First Service (Week 3)

**Week 3: Add OpenTelemetry to Claims Service (Pilot)**

1. **Add OpenTelemetry dependencies** to `pom.xml`:
   ```xml
   <dependencies>
     <!-- OpenTelemetry BOM for version management -->
     <dependency>
       <groupId>io.opentelemetry</groupId>
       <artifactId>opentelemetry-bom</artifactId>
       <version>1.32.0</version>
       <type>pom</type>
       <scope>import</scope>
     </dependency>

     <!-- OpenTelemetry API -->
     <dependency>
       <groupId>io.opentelemetry</groupId>
       <artifactId>opentelemetry-api</artifactId>
     </dependency>

     <!-- OpenTelemetry SDK -->
     <dependency>
       <groupId>io.opentelemetry</groupId>
       <artifactId>opentelemetry-sdk</artifactId>
     </dependency>

     <!-- OpenTelemetry Exporter (OTLP) -->
     <dependency>
       <groupId>io.opentelemetry</groupId>
       <artifactId>opentelemetry-exporter-otlp</artifactId>
     </dependency>

     <!-- OpenTelemetry Auto-instrumentation for Spring Boot -->
     <dependency>
       <groupId>io.opentelemetry.instrumentation</groupId>
       <artifactId>opentelemetry-spring-boot-starter</artifactId>
       <version>1.32.0-alpha</version>
     </dependency>

     <!-- OpenTelemetry Kafka instrumentation -->
     <dependency>
       <groupId>io.opentelemetry.instrumentation</groupId>
       <artifactId>opentelemetry-kafka-clients-2.6</artifactId>
       <version>1.32.0-alpha</version>
     </dependency>
   </dependencies>
   ```

2. **Configure OpenTelemetry** in `application.yml`:
   ```yaml
   otel:
     service:
       name: claims-service
     traces:
       exporter: otlp
     exporter:
       otlp:
         endpoint: http://otel-collector.observability.svc.cluster.local:4317
     metrics:
       exporter: none  # Disable metrics export (focus on traces)
     logs:
       exporter: none  # Disable logs export

   # Spring Boot OpenTelemetry auto-configuration
   spring:
     application:
       name: claims-service
   ```

3. **Add custom business logic spans** (optional but recommended):
   ```java
   package com.healthcare.claims;

   import io.opentelemetry.api.trace.Span;
   import io.opentelemetry.api.trace.Tracer;
   import io.opentelemetry.context.Scope;
   import org.springframework.beans.factory.annotation.Autowired;
   import org.springframework.stereotype.Service;

   @Service
   public class ClaimsService {

       @Autowired
       private Tracer tracer;

       @Autowired
       private KafkaTemplate<String, ClaimReceivedEvent> kafkaTemplate;

       public ClaimSubmissionResult submitClaim(ClaimRequest request) {
           // Auto-instrumentation creates span for this method call
           // Add custom span for business logic visibility
           Span span = tracer.spanBuilder("adjudicate-claim")
               .setAttribute("claim.id", request.getClaimId())
               .setAttribute("claim.amount", request.getTotalAmount())
               .setAttribute("member.id", request.getMemberId())
               .setAttribute("provider.id", request.getProviderId())
               .startSpan();

           try (Scope scope = span.makeCurrent()) {
               // Validate claim data
               validateClaim(request);
               span.addEvent("claim-validated");

               // Persist to database (auto-instrumented)
               Claim claim = claimRepository.save(request.toClaim());
               span.setAttribute("claim.status", claim.getStatus());
               span.addEvent("claim-persisted");

               // Publish event to Kafka (auto-instrumented, trace context propagated)
               ClaimReceivedEvent event = new ClaimReceivedEvent(claim.getId(), claim.getMemberId());
               kafkaTemplate.send("claims-received", event);
               span.addEvent("event-published");

               return ClaimSubmissionResult.success(claim.getId());

           } catch (ValidationException e) {
               span.recordException(e);
               span.setStatus(StatusCode.ERROR, "Validation failed");
               return ClaimSubmissionResult.validationError(e.getMessage());

           } catch (Exception e) {
               span.recordException(e);
               span.setStatus(StatusCode.ERROR, "Claim submission failed");
               throw e;

           } finally {
               span.end();
           }
       }
   }
   ```

4. **Propagate trace context through Kafka** (manual instrumentation):
   ```java
   package com.healthcare.claims.kafka;

   import io.opentelemetry.api.trace.Span;
   import io.opentelemetry.api.trace.propagation.W3CTraceContextPropagator;
   import io.opentelemetry.context.Context;
   import io.opentelemetry.context.propagation.TextMapSetter;
   import org.apache.kafka.common.header.Headers;
   import org.springframework.kafka.support.KafkaHeaders;
   import org.springframework.messaging.Message;
   import org.springframework.messaging.support.MessageBuilder;

   public class KafkaTracingProducer {

       private static final TextMapSetter<Headers> KAFKA_HEADER_SETTER =
           (carrier, key, value) -> carrier.add(key, value.getBytes());

       public <T> Message<T> injectTraceContext(T payload, String topic) {
           // Get current span context
           Context context = Context.current();

           // Create Kafka headers
           Headers headers = new RecordHeaders();

           // Inject trace context into headers using W3C Trace Context format
           W3CTraceContextPropagator.getInstance().inject(context, headers, KAFKA_HEADER_SETTER);

           // Build message with trace context in headers
           return MessageBuilder.withPayload(payload)
               .setHeader(KafkaHeaders.TOPIC, topic)
               .setHeader(KafkaHeaders.MESSAGE_KEY, payload.getId())
               .copyHeaders(headersToMap(headers))
               .build();
       }
   }
   ```

5. **Deploy instrumented service** and verify tracing:
   ```bash
   # Build and deploy
   ./mvnw clean package
   kubectl set image deployment/claims-service claims-service=claims-service:v2-otel

   # Submit test claim
   curl -X POST https://api.example.com/claims \
     -H "Content-Type: application/json" \
     -d '{"memberId": "M123", "providerId": "P456", "amount": 5000}'

   # Check Jaeger UI for trace
   # Search by service: claims-service
   # Search by operation: POST /claims
   # Search by tag: claim.id=C123456
   ```

