#### Example 3: Custom Span with Business Context

```java
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.context.Scope;

@Service
public class PricingService {

    @Autowired
    private Tracer tracer;

    @Autowired
    private FeeScheduleClient feeScheduleClient;

    public PricingResult calculatePricing(Claim claim) {
        Span span = tracer.spanBuilder("calculate-claim-pricing")
            .setAttribute("claim.id", claim.getId())
            .setAttribute("claim.total_amount", claim.getTotalAmount())
            .setAttribute("provider.network_status", claim.getProvider().getNetworkStatus())
            .startSpan();

        try (Scope scope = span.makeCurrent()) {
            // Apply fee schedules
            span.addEvent("applying-fee-schedules");
            FeeScheduleResponse feeSchedule = feeScheduleClient.getFeeSchedule(
                claim.getProvider().getId(),
                claim.getServiceDate()
            );
            span.setAttribute("fee_schedule.type", feeSchedule.getType());

            // Calculate allowed amount
            BigDecimal allowedAmount = feeSchedule.calculateAllowed(claim.getProcedureCodes());
            span.setAttribute("pricing.allowed_amount", allowedAmount);
            span.addEvent("allowed-amount-calculated");

            // Apply contract rates if network provider
            if (claim.getProvider().isInNetwork()) {
                span.addEvent("applying-contract-rates");
                ContractRate contractRate = getContractRate(claim.getProvider(), claim.getPlan());
                allowedAmount = contractRate.apply(allowedAmount);
                span.setAttribute("pricing.contract_rate_applied", true);
            }

            // Calculate provider payment
            BigDecimal providerPayment = allowedAmount.subtract(claim.getMemberCostSharing());
            span.setAttribute("pricing.provider_payment", providerPayment);

            span.setStatus(StatusCode.OK);
            return PricingResult.success(allowedAmount, providerPayment);

        } catch (FeeScheduleNotFoundException e) {
            span.recordException(e);
            span.setStatus(StatusCode.ERROR, "Fee schedule not found");
            return PricingResult.feeScheduleError(e.getMessage());

        } catch (Exception e) {
            span.recordException(e);
            span.setStatus(StatusCode.ERROR, "Pricing calculation failed");
            throw e;

        } finally {
            span.end();
        }
    }
}
```
